#include <stdio.h>

/* fimDeSemana le o dia digitado (1 = domingo ... 7 = sabado) e imprime
   "folga" quando o dia e de fim de semana. O domingo ja esta conferido.
   Falta o sabado: junte a segunda comparacao com || (dia == 7). */
void fimDeSemana(void) {
    int dia = 0;

    scanf("%d", &dia);

    if (dia == 1) {
        printf("folga\n");
    }
}

